import { Pressable, StyleSheet, Text, View } from '@/platform/react-native';
import { useLocalSearchParams, router } from '@/router';
import { useMutation,useQuery,useQueryClient } from '@tanstack/react-query';
import { Ionicons } from '@/platform/icons';
import { api } from '@/lib/api';
import { Badge, Button, Card, EmptyState, Muted, Screen } from '@/components/UI';
import { colors } from '@/theme';
import type { Alert } from '@/types';

export default function Alerts(){const{id}=useLocalSearchParams<{id:string}>();const qc=useQueryClient();const{data=[]}=useQuery<Alert[]>({queryKey:['alerts',id],queryFn:async()=>(await api.get(`/communities/${id}/alerts`)).data});const respond=useMutation({mutationFn:async(v:{alertId:string;response:string})=>api.post(`/alerts/${v.alertId}/respond`,{response:v.response}),onSuccess:()=>qc.invalidateQueries({queryKey:['alerts',id]})});return <Screen scroll><View style={styles.nav}><Pressable onPress={()=>(router.canGoBack()?router.back():router.replace('/'))}><Ionicons name="chevron-back" size={24}/></Pressable><Text style={styles.navTitle}>Emergency Alert</Text><Pressable accessibilityRole="button" accessibilityLabel="Create emergency alert" onPress={()=>router.push(`/community/${id}/manage`)}><Ionicons name="add-circle-outline" size={27} color={colors.danger}/></Pressable></View>{data.length?data.map(a=><View key={a.Id} style={styles.wrap}><View style={styles.redHeader}><Ionicons name="warning-outline" size={31} color="#fff"/><View style={{flex:1}}><Text style={styles.redTitle}>Emergency Alert</Text><Text style={styles.redName}>{a.Title}</Text><Text style={styles.time}>Issued {new Date(a.CreatedAt).toLocaleString()}</Text></View></View><Card style={styles.details}><Text style={styles.label}>Severity</Text><Badge text={a.Severity} tone={a.Severity==='CRITICAL'||a.Severity==='HIGH'?'red':'orange'}/><Text style={styles.label}>Details</Text><Text style={styles.body}>{a.Message}</Text>{a.AlertType?<><Text style={styles.label}>Alert Type</Text><Text style={styles.body}>{a.AlertType}</Text></>:null}{a.RequiresAcknowledgement?<View style={{marginTop:18}}><Button title="I'm Safe" variant="success" onPress={()=>respond.mutate({alertId:a.Id,response:'SAFE'})}/><Button title="I Need Help" variant="danger" onPress={()=>respond.mutate({alertId:a.Id,response:'NEED_HELP'})}/>{a.MyResponse?<Text style={styles.response}>Your response: {a.MyResponse.replace('_',' ')}</Text>:null}</View>:null}</Card></View>):<EmptyState icon="shield-checkmark-outline" title="No emergency alerts" body="There are currently no emergency alerts for this community."/>}</Screen>}
const styles=StyleSheet.create({nav:{flexDirection:'row',justifyContent:'space-between',alignItems:'center',height:52,marginBottom:10},navTitle:{fontSize:18,fontWeight:'900',color:colors.text},wrap:{marginBottom:18},redHeader:{backgroundColor:colors.danger,borderRadius:18,padding:18,flexDirection:'row',gap:13,alignItems:'flex-start'},redTitle:{fontSize:12,fontWeight:'800',color:'#FFD9D7'},redName:{fontSize:20,fontWeight:'900',color:'#fff',marginTop:2},time:{fontSize:11,color:'#FFE7E5',marginTop:5},details:{borderTopLeftRadius:0,borderTopRightRadius:0},label:{fontSize:12,fontWeight:'900',color:colors.text,marginTop:14,marginBottom:6},body:{fontSize:14,lineHeight:21,color:colors.text},response:{textAlign:'center',fontSize:12,color:colors.muted,fontWeight:'700',marginTop:8}})
